CREATE TYPE public.app_role AS ENUM ('admin','assistant');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '', phone text, can_prepare_pv boolean NOT NULL DEFAULT false, language text NOT NULL DEFAULT 'fr' CHECK (language IN ('fr','ar','en')), digest_time time NOT NULL DEFAULT '07:30', is_active boolean NOT NULL DEFAULT true, avatar_url text, push_tokens jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid);
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), created_by uuid, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.is_active_member() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND is_active) $$;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles ur JOIN public.profiles p ON p.id = ur.user_id WHERE ur.user_id = _user_id AND ur.role = _role AND p.is_active) $$;
CREATE FUNCTION public.is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT public.has_role(auth.uid(),'admin') $$;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING (public.is_active_member());
CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING (public.is_admin() OR (id = auth.uid() AND public.is_active_member())) WITH CHECK (public.is_admin() OR (id = auth.uid() AND public.is_active_member()));
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING (public.is_admin() OR (user_id = auth.uid() AND public.is_active_member()));
CREATE FUNCTION public.guard_profile_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NOT public.is_admin() THEN IF NEW.id <> OLD.id OR NEW.full_name IS DISTINCT FROM OLD.full_name OR NEW.phone IS DISTINCT FROM OLD.phone OR NEW.can_prepare_pv IS DISTINCT FROM OLD.can_prepare_pv OR NEW.is_active IS DISTINCT FROM OLD.is_active OR NEW.avatar_url IS DISTINCT FROM OLD.avatar_url OR NEW.push_tokens IS DISTINCT FROM OLD.push_tokens OR NEW.created_by IS DISTINCT FROM OLD.created_by THEN RAISE EXCEPTION 'Only administrators can manage team profiles'; END IF; END IF; NEW.updated_at := now(); RETURN NEW; END $$;
CREATE TRIGGER guard_profile_change BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.guard_profile_change();
CREATE FUNCTION public.guard_role_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF TG_OP = 'INSERT' AND NEW.role = 'assistant' AND (SELECT count(*) FROM public.user_roles WHERE role = 'assistant') >= 3 THEN RAISE EXCEPTION 'Maximum three assistants'; END IF; IF TG_OP = 'INSERT' AND NEW.role = 'admin' AND EXISTS (SELECT 1 FROM public.user_roles WHERE role = 'admin') THEN RAISE EXCEPTION 'Only one administrator is allowed'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_role_change BEFORE INSERT ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.guard_role_change();
CREATE FUNCTION public.create_invited_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles (id, full_name) VALUES (NEW.id, COALESCE(NEW.raw_user_meta_data->>'full_name','')); RETURN NEW; END $$;
CREATE TRIGGER create_invited_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_invited_profile();